import express from "express";
import { loginUser } from "./auth/login-service.js";
const app = express();
app.post("/login", (_req, res) => res.json(loginUser({ email: "user@example.com" })));

export function loginUser(input: { email?: string }) {
  if (!input.email) throw new Error("invalid login");
  return { sessionId: "session-1", token: "issued" };
}

import { expect, it } from "vitest";
import { loginUser } from "./login-service.js";
it("covers valid login", () => expect(loginUser({ email: "u@example.com" }).sessionId).toBe("session-1"));

export function loginUser(input: { email?: string }) {
  if (!input.email) throw new Error("missing login email");
  return { sessionId: "session-2", token: "issued" };
}
